from fractions import Fraction
from collections import deque

def solve():
    x0 = Fraction(11, 3)
    targets = [
        Fraction(7, 3),
        Fraction(11, 4),
        Fraction(2024, 5),
        Fraction(109, 11),
        Fraction(3, 71),
        Fraction(5, 204)
    ]

    distances = {}
    queue = deque([(x0, 0)])
    distances[x0] = 0

    while queue:
        x, d = queue.popleft()

        if d > 10: # Limit the search to 10 steps
            continue

        neighbors = []
        if x != 0: neighbors.append(-x)
        if x != Fraction(1, 2): neighbors.append(1-x)
        if x != 1 and x != -1 and x != 0: neighbors.append(1/x)

        for n in neighbors:
            if n not in distances:
                distances[n] = d + 1
                queue.append((n, d + 1))

    results = []
    for t in targets:
        if t in distances:
            results.append(distances[t])
        else:
            results.append(None)

    print(f"Distances: {results}")

solve()

